import 'audio/audio_backend.dart';

/// Sound effects + music. Files live in assets/audio (generated by
/// tool/gen_audio.py). Tests and headless runs use [SilentAudioService].
abstract class AudioService {
  Future<void> init();

  void setVolumes({double? sfx, double? music});

  /// Plays a one-shot effect, e.g. `sfx('splash', volume: 0.5)`.
  void sfx(String name, {double volume = 1});

  /// Switches the looping music track (cross-fades); null stops music.
  /// Asking for the track that is already playing does nothing.
  void music(String? track);

  /// Call on any user gesture. Browsers block audio until the first tap,
  /// so music requested before that starts here.
  void unlock();
}

class SilentAudioService implements AudioService {
  @override
  Future<void> init() async {}
  @override
  void setVolumes({double? sfx, double? music}) {}
  @override
  void sfx(String name, {double volume = 1}) {}
  @override
  void music(String? track) {}
  @override
  void unlock() {}
}

class GameAudioService implements AudioService {
  GameAudioService({double sfxVolume = 0.8, double musicVolume = 0.5, AudioBackend? backend})
    : _backend = backend ?? createAudioBackend() {
    _backend
      ..setSfxVolume(sfxVolume)
      ..setMusicVolume(musicVolume);
    _musicOn = musicVolume > 0.001;
  }

  static const effects = [
    'shot_pistol',
    'shot_rifle',
    'shot_launcher',
    'hit',
    'splash',
    'ui_click',
    'hurt',
    'tag_out',
    'pickup',
    'reload',
    'plant',
    'haze_warning',
    'win',
    'lose',
  ];
  static const tracks = ['music_menu', 'music_match'];

  final AudioBackend _backend;
  final Map<String, int> _lastPlayed = {};
  final Stopwatch _clock = Stopwatch()..start();
  String? _track;
  bool _musicOn = true;

  @override
  Future<void> init() => _backend.load(effects, tracks);

  @override
  void setVolumes({double? sfx, double? music}) {
    if (sfx != null) _backend.setSfxVolume(sfx);
    if (music != null) {
      _backend.setMusicVolume(music);
      final on = music > 0.001;
      if (on != _musicOn) {
        _musicOn = on;
        this.music(_track);
      }
    }
  }

  @override
  void sfx(String name, {double volume = 1}) {
    if (volume < 0.02) return;
    // Don't stack the same sound within 30 ms (25 bots can fire at once).
    final now = _clock.elapsedMilliseconds;
    if (now - (_lastPlayed[name] ?? -1000) < 30) return;
    _lastPlayed[name] = now;
    _backend.playSfx(name, volume.clamp(0.0, 1.0));
  }

  @override
  void music(String? track) {
    _track = track;
    if (track == null || !_musicOn) {
      _backend.stopMusic();
    } else {
      _backend.playMusic(track);
    }
  }

  @override
  void unlock() {
    if (!_backend.unlocked) _backend.unlock();
  }
}
